class Solution { private final Map<Integer,Integer> counts=new HashMap<>();private int best;public int[] findFrequentTreeSum(TreeNode root){dfs(root);return counts.entrySet().stream().filter(e->e.getValue()==best).mapToInt(Map.Entry::getKey).sorted().toArray();}private int dfs(TreeNode node){if(node==null)return 0;int sum=node.val+dfs(node.left)+dfs(node.right);int count=counts.getOrDefault(sum,0)+1;counts.put(sum,count);best=Math.max(best,count);return sum;} }
